// Extract transcript download URL from recording files
const recordingFiles = $json.recording_files || [];

const transcriptFile = recordingFiles.find(f => f.file_type === 'TRANSCRIPT');

if (!transcriptFile || !transcriptFile.download_url) {
  throw new Error('No TRANSCRIPT file found in this meeting recording. Make sure Auto-Transcription is enabled in Zoom settings.');
}

const meetingId = $json.id || $json.uuid;
const meetingTopic = $json.topic || 'Untitled Meeting';
const meetingStartTime = $json.start_time || new Date().toISOString();
const meetingDuration = $json.duration || 0;

return [{
  json: {
    transcriptUrl: transcriptFile.download_url,
    meetingId,
    meetingTopic,
    meetingStartTime,
    meetingDuration,
    formattedDate: new Date(meetingStartTime).toLocaleString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }
}];

// Parse Zoom VTT transcript format into clean readable text
const rawTranscript = $json.data || $json.body || '';

if (!rawTranscript || rawTranscript.trim().length === 0) {
  throw new Error('Downloaded transcript is empty. The meeting may not have audio or transcription may still be processing.');
}

const blocks = rawTranscript.split(/\r?\n\r?\n/);
const lines = [];

for (const block of blocks) {
  const blockLines = block.trim().split(/\r?\n/);
  if (blockLines[0] === 'WEBVTT' || blockLines.length < 2) continue;

  let startIndex = 0;
  if (/^\d+$/.test(blockLines[0])) startIndex = 1;
  if (blockLines[startIndex] && blockLines[startIndex].includes('-->')) startIndex++;

  const textLines = blockLines.slice(startIndex).join(' ').trim();
  if (textLines) lines.push(textLines);
}

const cleanTranscript = lines.join('\n');
const meta = $('6. Code — Extract Transcript URL').item.json;

return [{
  json: {
    transcript: cleanTranscript,
    transcriptWordCount: cleanTranscript.split(/\s+/).length,
    meetingId: meta.meetingId,
    meetingTopic: meta.meetingTopic,
    meetingStartTime: meta.meetingStartTime,
    meetingDuration: meta.meetingDuration,
    formattedDate: meta.formattedDate
  }
}];

