// Format AI summary into clean HTML email and split participants
const summaryRaw = $('10. Claude 3.7 — Generate Meeting Summary').item.json.output || '';
const participants = $('9. Zoom — Get All Participants').item.json.participants || [];
const meetingTopic = $('8. Code — Parse Transcript Text').item.json.meetingTopic;
const formattedDate = $('8. Code — Parse Transcript Text').item.json.formattedDate;
const meetingDuration = $('8. Code — Parse Transcript Text').item.json.meetingDuration;
const meetingId = $('8. Code — Parse Transcript Text').item.json.meetingId;

const formatSection = (text) => {
  return text
    .replace(/## (.+)/g, '<h2 style="color:#1a1a1a;font-size:18px;margin:20px 0 8px;border-bottom:2px solid #e0e0e0;padding-bottom:6px;">$1</h2>')
    .replace(/^- (.+)/gm, '<li style="margin-bottom:6px;">$1</li>')
    .replace(/(<li[^>]*>.*<\/li>\n?)+/g, '<ul style="padding-left:20px;margin:8px 0;">$&</ul>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\n\n/g, '</p><p style="margin:8px 0;">')
    .replace(/^(?!<)(.+)/gm, '<p style="margin:8px 0;line-height:1.6;color:#444;">$1</p>');
};

const htmlBody = `
<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"></head>
<body style="font-family:Arial,sans-serif;max-width:700px;margin:0 auto;background:#f4f4f4;">
  <div style="background:#1a1a1a;padding:28px 32px;border-radius:8px 8px 0 0;">
    <h1 style="color:#ffffff;font-size:22px;margin:0;">Meeting Summary</h1>
    <p style="color:#aaaaaa;font-size:13px;margin:8px 0 0;">${meetingTopic}</p>
  </div>
  <div style="background:#0066cc;padding:10px 32px;">
    <p style="color:#ffffff;font-size:13px;margin:0;">${formattedDate} &nbsp;•&nbsp; ${meetingDuration} minutes &nbsp;•&nbsp; ${participants.length} participants</p>
  </div>
  <div style="background:#ffffff;padding:24px 32px;">
    ${formatSection(summaryRaw)}
  </div>
  <div style="background:#f9f9f9;padding:16px 32px;border-top:1px solid #e0e0e0;">
    <p style="font-size:12px;color:#888;margin:0;">This summary was generated automatically using Claude 3.7 Sonnet AI.</p>
    <p style="font-size:12px;color:#888;margin:4px 0 0;">Meeting ID: ${meetingId}</p>
  </div>
  <div style="background:#1a1a1a;padding:12px 32px;border-radius:0 0 8px 8px;">
    <p style="color:#888;font-size:11px;margin:0;">Powered by n8n + Claude 3.7 Sonnet</p>
  </div>
</body>
</html>`;

const uniqueParticipants = [];
const seenEmails = new Set();
for (const p of participants) {
  if (p.user_email && !seenEmails.has(p.user_email)) {
    seenEmails.add(p.user_email);
    uniqueParticipants.push({ name: p.name || 'Participant', email: p.user_email });
  }
}

return uniqueParticipants.map(participant => ({
  json: {
    participantName: participant.name,
    participantEmail: participant.email,
    htmlEmail: htmlBody,
    emailSubject: `Meeting Summary: ${meetingTopic} — ${formattedDate}`,
    summaryRaw,
    meetingTopic,
    formattedDate,
    meetingDuration,
    meetingId,
    totalParticipants: uniqueParticipants.length
  }
}));

// Extract action items from AI summary
const summaryRaw = $('11. Code — Format Email + Split Participants').item.json.summaryRaw;
const meetingTopic = $('11. Code — Format Email + Split Participants').item.json.meetingTopic;

const actionItemsMatch = summaryRaw.match(/## Action Items\n([\s\S]*?)(?=\n## |$)/);
const actionItemsSection = actionItemsMatch ? actionItemsMatch[1].trim() : '';

if (!actionItemsSection || actionItemsSection.toLowerCase() === 'none') {
  return [{ json: { hasTasks: false, tasks: [] } }];
}

const taskLines = actionItemsSection.split('\n').filter(l => l.trim().startsWith('-'));

const tasks = taskLines.map(line => {
  const cleanLine = line.replace(/^-\s*/, '').trim();
  const taskMatch = cleanLine.match(/^(.+?):\s*(.+?)\s*\|\s*Due:\s*(.+?)\s*\|\s*Priority:\s*(High|Medium|Low)/i);

  if (taskMatch) {
    return {
      name: taskMatch[1].trim(),
      description: `Action item from meeting: ${meetingTopic}\n\nAssigned to: ${taskMatch[2].trim()}\n\nFull context: ${cleanLine}`,
      owner: taskMatch[2].trim(),
      dueDate: taskMatch[3].trim().toLowerCase() === 'not specified' ? '' : taskMatch[3].trim(),
      priority: taskMatch[4].toLowerCase()
    };
  }

  return {
    name: cleanLine.substring(0, 100),
    description: `Action item from meeting: ${meetingTopic}\n\nFull context: ${cleanLine}`,
    owner: 'Unassigned',
    dueDate: '',
    priority: 'normal'
  };
}).filter(t => t.name.length > 2);

return [{ json: { hasTasks: tasks.length > 0, tasks, taskCount: tasks.length } }];

// Extract follow-up meeting info from AI summary
const summaryRaw = $('11. Code — Format Email + Split Participants').item.json.summaryRaw;
const meetingTopic = $('11. Code — Format Email + Split Participants').item.json.meetingTopic;

const followUpMatch = summaryRaw.match(/## Follow-up Meeting\n([\s\S]*?)(?=\n## |$)/);
const followUpSection = followUpMatch ? followUpMatch[1].trim() : '';

if (!followUpSection || followUpSection.toLowerCase().includes('none scheduled')) {
  return [{ json: { hasFollowUp: false } }];
}

const dateMatch = followUpSection.match(/Date:\s*(.+)/);
const topicMatch = followUpSection.match(/Topic:\s*(.+)/);

const followUpDate = dateMatch ? dateMatch[1].trim() : '';
const followUpTopic = topicMatch ? topicMatch[1].trim() : `Follow-up: ${meetingTopic}`;

let startDateTime;
let endDateTime;
try {
  const parsedDate = new Date(followUpDate);
  if (isNaN(parsedDate.getTime())) {
    const nextTuesday = new Date();
    nextTuesday.setDate(nextTuesday.getDate() + ((2 - nextTuesday.getDay() + 7) % 7 || 7));
    nextTuesday.setHours(10, 0, 0, 0);
    startDateTime = nextTuesday.toISOString();
    endDateTime = new Date(nextTuesday.getTime() + 60 * 60 * 1000).toISOString();
  } else {
    startDateTime = parsedDate.toISOString();
    endDateTime = new Date(parsedDate.getTime() + 60 * 60 * 1000).toISOString();
  }
} catch (e) {
  const nextTuesday = new Date();
  nextTuesday.setDate(nextTuesday.getDate() + 7);
  nextTuesday.setHours(10, 0, 0, 0);
  startDateTime = nextTuesday.toISOString();
  endDateTime = new Date(nextTuesday.getTime() + 60 * 60 * 1000).toISOString();
}

return [{
  json: {
    hasFollowUp: true,
    followUpTitle: followUpTopic,
    startDateTime,
    endDateTime,
    originalSection: followUpSection
  }
}];

